export enum Status {
  Draft = 0,
  Paid = 1,
  Shipped = 2,
  Delivered = 3,
  Cancelled = 9,
}

export enum RefundStatus {
  None = 0,
  Pending = 1,
  Cancelled = 7,
  Done = 8,
}

