export function sumOrder0(xs: number[]): number {
  return xs.reduce((acc, x) => acc + x, 0);
}

export const lineLabel1 = (id: number): string => `line-${id}`;

export function slugOrder2(text: string): string {
  return text.trim().toLowerCase().replace(/\s+/g, '-');
}
